INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c926-78ed-9ecc-ea079d01fd5d'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'The force F between two objects is inversely proportional to the square of their separation d. If the separation is increased by 80%, calculate the percentage decrease in F.', '69.1%', 'The new distance is 1.8d. Hence, the new force is F/(1.8²) = F/3.24 ≈ 0.3086F. Percentage decrease = (1 - 0.3086) × 100% ≈ 69.1%.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.166Z'::timestamptz, '2026-08-15T07:50:40.166Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c930-79ea-892b-14f1a6153c6c'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'The expression 6 - 8x - x² can be written in the form k - (x - h)². Find h and k, and state the maximum value of the expression.', 'h = -4, k = 22, maximum value = 22', '6 - 8x - x² = 6 - (x² + 8x + 16) + 16 = 22 - (x + 4)². Thus h = -4 and k = 22. Maximum value is 22 when x = -4.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.176Z'::timestamptz, '2026-08-15T07:50:40.176Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c93c-77d8-a8aa-50e219eb2d2f'::uuid, '019f9df7-a2a2-7877-afdf-c436930f3059'::uuid, 'Solve the simultaneous equations 3x + 2y = 19 and 5x - y = 13.', 'x = 3.46 (45/13), y = 4.31 (56/13)', 'From 5x - y = 13, y = 5x - 13. Substitute into the first equation: 3x + 2(5x - 13) = 19, so 13x = 45 and x = 45/13. Then y = 5(45/13) - 13 = 56/13.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.188Z'::timestamptz, '2026-08-15T07:50:40.188Z'::timestamptz) ON CONFLICT (id) DO NOTHING;